def signal(obs):
    # state: last target and hold counter
    s = obs.state
    # initialize
    if 'pos_C' not in s:
        s['pos_C'] = 0.0
        s['hold'] = 0
    # get histories
    try:
        imb_hist = obs.hist('C','imbalance',20)
        mid_hist = obs.hist('C','mid',60)
    except:
        return {'C': float(s['pos_C']), 'A':0.0,'B':0.0,'IDX':0.0,'A.X':0.0,'B.X':0.0,'C.X':0.0}
    # compute signal: EWMA of imbalance over last 10
    # nan handling
    if len(imb_hist)<10:
        return {'C': float(s['pos_C']), 'A':0.0,'B':0.0,'IDX':0.0,'A.X':0.0,'B.X':0.0,'C.X':0.0}
    last10 = imb_hist[-10:]
    # nan mean
    m = float(np.nanmean(last10))
    if np.isnan(m):
        # keep hold
        s['hold'] = s['hold']+1 if 'hold' in s else 1
        return {'C': float(s['pos_C']), 'A':0.0,'B':0.0,'IDX':0.0,'A.X':0.0,'B.X':0.0,'C.X':0.0}
    # momentum filter: past 50 return
    past_ret = 0.0
    if len(mid_hist)>=55 and not np.isnan(mid_hist[-1]) and not np.isnan(mid_hist[-51]):
        past_ret = float(mid_hist[-1] - mid_hist[-51])
    # decide desired position
    desired = 0.0
    # strong imbalance threshold
    if m > 0.6:
        desired = 0.8
        # momentum reinforces: if past_ret also positive, increase to 1.0
        if past_ret > 3:
            desired = 1.0
    elif m < -0.6:
        desired = -0.8
        if past_ret < -3:
            desired = -1.0
    elif abs(m) < 0.35:
        desired = 0.0
    else:
        # moderate imbalance keep previous to reduce turnover
        desired = float(s['pos_C'])
    # hold constraint: prevent flip-flop before 5 signal calls (50 steps)
    # signal called every 10 steps, so 5 calls = 50 steps, we want 10 calls =100 steps for full hold
    # if we want to change sign, require hold >=8 calls
    # else keep old
    if desired * s['pos_C'] < 0:  # sign flip
        if s['hold'] < 8:
            desired = float(s['pos_C'])
        else:
            s['hold'] = 0
    # if desired changed magnitude but not sign, allow after 3 holds
    if desired != s['pos_C']:
        if s['hold'] < 3 and abs(desired) < abs(s['pos_C']):
            # delay reducing position too quickly? keep
            pass
    # update hold counter
    if desired == s['pos_C']:
        s['hold'] = s['hold'] + 1
    else:
        s['hold'] = 0
        s['pos_C'] = float(desired)
    # cheap venues only, hedge others flat
    return {'C': float(s['pos_C']), 'A':0.0,'B':0.0,'IDX':0.0,'A.X':0.0,'B.X':0.0,'C.X':0.0}

def signal(obs):
    s = obs.state
    if 'prev_C' not in s:
        s['prev_C'] = 0.0
    # histories, tolerate failure
    try:
        c_mid = obs.hist('C','mid',80)
        c_imb = obs.hist('C','imbalance',15)
        c_spread = obs.hist('C','spread',15)
    except:
        return {'C': float(s['prev_C']), 'A': 0.0, 'B': 0.0, 'IDX': 0.0, 'A.X': 0.0, 'B.X': 0.0, 'C.X': 0.0}
    # nan check - if recent missing, keep prev
    if len(c_mid) < 60 or np.isnan(c_mid[-1]) or np.isnan(c_mid[-51]):
        raw = s['prev_C']
        return {'C': float(raw), 'A': 0.05, 'B': 0.15, 'IDX': 0.0, 'A.X': 0.0, 'B.X': 0.0, 'C.X': 0.0}
    # baseline long bias to capture drift (market up ~0.05 per step)
    baseline = 0.35
    # 50-step momentum
    past50 = float(c_mid[-1] - c_mid[-51])
    mom = 0.0
    if past50 > 6:
        mom = 0.45
    elif past50 > 2:
        mom = 0.20
    elif past50 < -6:
        mom = -0.45
    elif past50 < -2:
        mom = -0.20
    # imbalance signal - average last 5
    imb_val = float(np.nanmean(c_imb[-5:]))
    if np.isnan(imb_val):
        imb_sig = 0.0
    else:
        if imb_val > 0.45:
            imb_sig = 0.45
        elif imb_val > 0.25:
            imb_sig = 0.25
        elif imb_val < -0.45:
            imb_sig = -0.45
        elif imb_val < -0.25:
            imb_sig = -0.25
        else:
            imb_sig = 0.0
    # combine
    raw_desired = baseline + mom + imb_sig
    # clip
    if raw_desired > 1: raw_desired = 1
    if raw_desired < -1: raw_desired = -1
    # smooth to reduce turnover and improve Sharpe : EWMA 0.35
    prev = float(s['prev_C'])
    smoothed = 0.65 * prev + 0.35 * raw_desired
    # small deadband to avoid churn
    if abs(smoothed - prev) < 0.07:
        smoothed = prev
    # also avoid shorting too aggressively on strong up drift: floor at -0.3
    if smoothed < -0.3:
        # allow short only if both mom and imb negative strong
        if not (mom < -0.3 and imb_sig < -0.3):
            smoothed = -0.3
            if prev > 0:
                smoothed = 0.0
    s['prev_C'] = float(smoothed)
    # keep other assets small long bias low turnover cheap venues, neutral expensive venues and IDX
    # A and B small baseline longs to add drift diversification with low cost (0 fee venues)
    # they also have momentum but weaker; we keep them static to avoid turnover
    return {'C': float(smoothed), 'A': 0.10, 'B': 0.15, 'IDX': 0.0, 'A.X': 0.0, 'B.X': 0.0, 'C.X': 0.0}

