  d=a-b
  m=np.isfinite(d)
  dm=d[m]
  res[pairs[k][0]]={'mean':float(np.mean(dm)),'std':float(np.std(dm)),'meanabs':float(np.mean(np.abs(dm))),'maxabs':float(np.max(np.abs(dm)))}
