def signal(obs):
    wA=0.3333; wB=0.6667; wC=0.1667
    a=obs.last('A','mid'); b=obs.last('B','mid'); c=obs.last('C','mid'); idx=obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None:
        return {}
    import math as m
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    synth=wA*a+wB*b+wC*c
    diff=idx-synth
    # threshold 5, linear sizing capped
    s=0.0
    thr=5.0
    cap=12.0
    if diff>thr:
        s=min(1.0,(diff-thr)/(cap-thr))
    elif diff<-thr:
        s=max(-1.0,(diff+thr)/(cap-thr))
    else:
        s=0.0
    # if IDX rich (s>0): short IDX, long components
    return {'IDX':-s,'A':s*wA,'B':s*wB,'C':s*wC}

def signal(obs):
    imb=obs.last('C','imbalance')
    if imb is None or imb!=imb:
        return {}
    s=max(-1.0,min(1.0,imb*2.0))
    # only trade extremes
    if abs(imb)<0.2:
        s=0.0
    return {'C':s}

def signal(obs):
    # cross venue arb A vs A.X
    a=obs.last('A','mid'); ax=obs.last('A.X','mid')
    b=obs.last('B','mid'); bx=obs.last('B.X','mid')
    c=obs.last('C','mid'); cx=obs.last('C.X','mid')
    out={}
    def arb(primary, alt, p, q):
        if p is None or q is None or p!=p or q!=q:
            return (0,0)
        d=p-q
        thr=4.0
        cap=10.0
        s=0.0
        if d>thr: s=min(1.0,(d-thr)/(cap-thr))
        elif d<-thr: s=max(-1.0,(d+thr)/(cap-thr))
        # if primary rich (d>0): short primary, long alt => primary -s, alt +s
        return (-s, s)
    sa,sax=arb('A','A.X',a,ax)
    sb,sbx=arb('B','B.X',b,bx)
    sc,scx=arb('C','C.X',c,cx)
    return {'A':sa,'A.X':sax,'B':sb,'B.X':sbx,'C':sc,'C.X':scx}

