  mid=H[asset]['mid']
  n=len(mid)
  for h in [10,50,100]:
    fwd=np.empty_like(mid); fwd[:]=np.nan
    for i in range(n-h):
      if np.isfinite(mid[i+h]) and np.isfinite(mid[i]):
        fwd[i]=mid[i+h]-mid[i]
    m=np.isfinite(imb[:n-h])&np.isfinite(fwd[:n-h])
    imbv=imb[:n-h][m]; fwdv=fwd[:n-h][m]
    c=float(np.corrcoef(imbv,fwdv)[0,1]) if len(imbv)>20 else 0
    hi=fwdv[imbv>0.3]; lo=fwdv[imbv<-0.3]
    mh=float(np.mean(hi)) if len(hi)>5 else 0
    ml=float(np.mean(lo)) if len(lo)>5 else 0
    out[asset+'_h'+str(h)]={'corr':c,'mean_hi':mh,'mean_lo':ml,'nhi':int(len(hi)),'nlo':int(len(lo)),'fwd_std':float(np.std(fwdv))}
result=out

