  for h in [10,50,100]:
    past=np.empty_like(mid); fwd=np.empty_like(mid)
    past[:]=np.nan; fwd[:]=np.nan
    for i in range(h,n-h):
      if np.isfinite(mid[i]) and np.isfinite(mid[i-h]):
        past[i]=mid[i]-mid[i-h]
      if np.isfinite(mid[i+h]) and np.isfinite(mid[i]):
        fwd[i]=mid[i+h]-mid[i]
    m=np.isfinite(past)&np.isfinite(fwd)
    pv=past[m]; fv=fwd[m]
    c=float(np.corrcoef(pv,fv)[0,1]) if len(pv)>20 else 0
    out[asset+'_h'+str(h)]={'corr':c}
result=out

def signal(obs):
    a=obs.last('A','mid'); b=obs.last('B','mid'); c=obs.last('C','mid'); idx=obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None:
        return {}
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    synth=0.3333*a+0.6667*b+0.1667*c
    diff=idx-synth
    thr=6.0
    s=0.0
    if diff>thr: s=1.0
    elif diff<-thr: s=-1.0
    else: s=0.0
    if s==0.0:
        return {'IDX':0.0,'A':0.0,'B':0.0,'C':0.0}
    return {'IDX':-s,'A':s*0.3333,'B':s*0.6667,'C':s*0.1667}

