    s = obs.state
    # Base long bias on B (best drift/std, zero-fee venue), plus slow A-momentum tilt (stable lead-lag A->B).
    # Slow-moving => very low turnover to survive ~10c spreads.
    try:
        ha = obs.hist('A', 'mid', 65)
    except Exception:
        ha = None
    tilt = 0.0
    if ha is not None:
        try:
            n = len(ha)
            if n >= 61:
                a_now = ha[n-1]
                a_old = ha[n-51]
                if a_now == a_now and a_old == a_old and a_now > 0 and a_old > 0:
                    r = a_now - a_old
                    # scale: std ~3.6c; clip at +-8c
                    if r > 8.0:
                        r = 8.0
                    if r < -8.0:
                        r = -8.0
                    tilt = r / 8.0
        except Exception:
            tilt = 0.0
    # smooth tilt to cut turnover
    prev_t = s.get('t', 0.0)
    if tilt != tilt:
        tilt = 0.0
    t = 0.9 * prev_t + 0.1 * tilt
    s['t'] = t
    b_sig = 0.65 + 0.35 * t
    if b_sig > 1.0:
        b_sig = 1.0
    if b_sig < -1.0:
        b_sig = -1.0
    # keep a small diversified long bias on C primary? No: keep single leg to minimize spread costs.
    return {'B': b_sig}

