def signal(obs):
    W=300; k=2.0
    # threshold larger k reduces size
    try:
        n=320
        a=obs.hist('A','mid',n); b=obs.hist('B','mid',n); c=obs.hist('C','mid',n); idx=obs.hist('IDX','mid',n)
        if a is None or len(a)<W+1: return {}
        syn=0.3333*a+0.6667*b+0.1667*c
        prem=idx-syn
        window=prem[-W-1:-1]
        valid=window[~np.isnan(window)]
        if len(valid)<200: return {}
        m=np.mean(valid); s=np.std(valid)
        if s<10: s=10
        cur=prem[-1]
        if np.isnan(cur): return {}
