        # hysteretic deadzone 1.0 enter, 0.3 exit - implement state
        # use obs.state to remember position
        prev_t=obs.state.get('t',0.0)
        # decide target based on z and prev
        if abs(z)<0.3:
            t=0.0
        elif abs(z)>1.0:
            t=float(-np.clip(z/k, -1, 1))
        else:
            # if already in position, keep; else 0
            if prev_t!=0:
                t=float(-np.clip(z/k, -1, 1))
            else:
                t=0.0
        obs.state['t']=t
        return {"IDX":t, "A":-t*0.3333, "B":-t*0.6667, "C":-t*0.1667}
    except Exception:
        return {}

