        idx = obs.hist('IDX', 'mid', n)
        if a is None or b is None or c is None or idx is None:
            return {}
        if len(a) < W+5 or len(idx) < W+5:
            return {}
        syn = 0.3333*a + 0.6667*b + 0.1667*c
        prem = idx - syn
        # window excludes current bar
        window = prem[-W-1:-1]
        # filter NaNs
        valid = window[~np.isnan(window)]
        if len(valid) < 300:
            # keep previous signal
            p = obs.state.get('p', 0.0)
            return {"IDX": float(p), "A": float(-p*0.3333), "B": float(-p*0.6667), "C": float(-p*0.1667), "A.X": 0.0, "B.X": 0.0, "C.X": 0.0}
        m = np.median(valid)
        mad = np.median(np.abs(valid - m))
        s = mad * 1.4826
        if s < 15:
            s = 15
        # cap extreme s to avoid no trading in volatile regimes
        if s > 200:
            s = 200
        cur = prem[-1]
        if np.isnan(cur) or np.isnan(m) or np.isnan(s):
