def safe_corr(x,y):
    m=np.isfinite(x)&np.isfinite(y)
    if np.sum(m)<30:
        return float('nan')
    x=x[m]; y=y[m]
    if np.std(x)==0 or np.std(y)==0:
        return float('nan')
    return float(np.corrcoef(x,y)[0,1])
def autocorr(x,lag):
    x=np.array(x)
    m=np.isfinite(x)
    x=x[m]
    if len(x)<lag+10:
        return float('nan')
    return safe_corr(x[:-lag], x[lag:])

